#!/usr/bin/env python3
"""Verify direct fixed-codeword likelihood ratios and Bhattacharyya trial bound."""
from hashlib import sha256
from pathlib import Path
import json
import sympy as s
ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/direct_codeword_likelihood_avoids_inverse_calibration_amplification.md';CAL=ROOT/'research/voevodsky/results/finite_count_parity_calibration.json';OLD=ROOT/'research/voevodsky/results/inverse_calibration_parity_sample_bound.json';E2E=ROOT/'research/voevodsky/results/end_to_end_null_channel.json';RESULT=ROOT/'research/voevodsky/results/direct_codeword_likelihood_bound.json';cal=json.loads(CAL.read_text(encoding='utf-8'));R=s.Matrix([[s.Rational(x) for x in row] for row in cal['single_response']]);p0=list(R[:,0]);p1=list(R[:,1]);bc=s.simplify(sum(s.sqrt(x*y) for x,y in zip(p0,p1)));N=s.ceiling(s.log(s.Rational(1,20))/s.log(bc));old=json.loads(OLD.read_text(encoding='utf-8'));e2e=json.loads(E2E.read_text(encoding='utf-8'));text=PACKET.read_text(encoding='utf-8');checks={'source_response':cal['passed'],'p0_exact':p0==[s.Rational(9,10),s.Rational(1,10),0,0],'p1_exact':p1==[s.Rational(72,125),s.Rational(97,250),s.Rational(9,250),0],'likelihood_zero':s.factor(p1[0]/p0[0])==s.Rational(16,25),'likelihood_one':s.factor(p1[1]/p0[1])==s.Rational(97,25),'count_two_conclusive':p0[2]==0 and p1[2]>0,'bhattacharyya_exact':bc==s.Rational(18,25)+s.sqrt(97)/50,'trial_bound_35':N==35,'improves_declared_generic_bound':N<old['sufficient_trials'],'all_four_codewords_prior':e2e['checks']['all_classes_decoded'],'fixed_codeword_scope':'does not apply to arbitrary mixtures, drifting preparations, or unvalidated response parameters' in text,'goodness_of_fit_gate':'Held-out goodness-of-fit' in text};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.direct-codeword-likelihood-bound.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'calibration_result_sha256':sha256(CAL.read_bytes()).hexdigest(),'generic_bound_result_sha256':sha256(OLD.read_bytes()).hexdigest(),'p0':[str(x) for x in p0],'p1':[str(x) for x in p1],'bhattacharyya_coefficient':str(bc),'total_error_target':'1/20','sufficient_trials':int(N),'checks':checks,'passed':all(checks.values()),'disposition':{'fixed_codeword_classifier':'35-trial sufficient bound','generic_distribution_inversion':old['sufficient_trials'],'mixture_or_code_leakage':'requires goodness-of-fit rejection'}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
